package com.qfc.rag;
import com.baomidou.mybatisplus.annotation.*; import java.time.LocalDateTime;
@TableName("knowledge_file") public class KnowledgeFile { @TableId(type=IdType.AUTO) private Long id; private Long projectId,fileId; private Boolean included,sensitive; private String status,errorMessage; private LocalDateTime sourceUpdatedAt,indexedAt,createdAt,updatedAt; public Long getId(){return id;} public void setId(Long v){id=v;} public Long getProjectId(){return projectId;} public void setProjectId(Long v){projectId=v;} public Long getFileId(){return fileId;} public void setFileId(Long v){fileId=v;} public Boolean getIncluded(){return included;} public void setIncluded(Boolean v){included=v;} public Boolean getSensitive(){return sensitive;} public void setSensitive(Boolean v){sensitive=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public String getErrorMessage(){return errorMessage;} public void setErrorMessage(String v){errorMessage=v;} public LocalDateTime getSourceUpdatedAt(){return sourceUpdatedAt;} public void setSourceUpdatedAt(LocalDateTime v){sourceUpdatedAt=v;} public LocalDateTime getIndexedAt(){return indexedAt;} public void setIndexedAt(LocalDateTime v){indexedAt=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){createdAt=v;} public LocalDateTime getUpdatedAt(){return updatedAt;} public void setUpdatedAt(LocalDateTime v){updatedAt=v;} }
